// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, uniqueSuffix } from '@skyramp/skyramp';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:2368");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Ghost " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const newsletterName = uniqueSuffix("Editor Plus Weekly");

    // Request Body
    const endpoint1PostRequestBody: string = `{
        "newsletters": [
            {
                "description": "Exercises the Editor Plus newsletter add grant",
                "name": "Editor Plus Weekly"
            }
        ]
    }`;

    // Execute Request
    const endpoint1PostResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/ghost/api/admin/newsletters/",
        method: "POST",
        body: endpoint1PostRequestBody,
        headers: headers,
        dataOverride: {"newsletters.0.name": newsletterName}
    });

    // Generated Assertions
    expect(endpoint1PostResponse.statusCode, 'status code').toBe(201);
    expect(getValue(endpoint1PostResponse, "newsletters.0.name"), 'name').toBe(newsletterName);
    expect(getValue(endpoint1PostResponse, "newsletters.0.description"), 'description').toBe("Exercises the Editor Plus newsletter add grant");
    expect(getValue(endpoint1PostResponse, "newsletters.0.id"), 'id').toMatch(/^[0-9a-f]{24}$/i);
    expect(getValue(endpoint1PostResponse, "newsletters.0.status"), 'status').toBe("active");
    expect(getValue(endpoint1PostResponse, "newsletters.0.created_at"), 'created_at').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getValue(endpoint1PostResponse, "newsletters.1.id"), 'newsletters.1').toBeNull();
    expect(JSON.parse(endpoint1PostResponse.responseBody).errors, 'errors').toBeUndefined();

    // Execute Request
    const endpoint1GetResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/ghost/api/admin/newsletters/",
        method: "GET",
        headers: headers,
        queryParams: {"limit": ["all"]}
    });

    // Generated Assertions
    expect(endpoint1GetResponse.statusCode, 'status code').toBe(200);
    const createdNewsletterId = getValue(endpoint1PostResponse, "newsletters.0.id");
    const browseBody = JSON.parse(endpoint1GetResponse.responseBody);
    expect(browseBody.errors, 'errors').toBeUndefined();
    expect(Array.isArray(browseBody.newsletters), 'newsletters is array').toBe(true);
    expect(browseBody.newsletters.length, 'newsletters length').toBeGreaterThan(0);
    const persistedNewsletter = browseBody.newsletters.find((n: any) => n.id === createdNewsletterId);
    expect(persistedNewsletter, 'created newsletter present in browse').toBeDefined();
    expect(persistedNewsletter.name, 'persisted name').toBe(newsletterName);
    expect(persistedNewsletter.status, 'persisted status').toBe("active");
});
